```cpp
#include <WiFi.h>
#include <PubSubClient.h>

const char* SSID = "...";
const char* PASS = "...";
const char* BROKER = "192.168.1.10";      // IP del Raspberry

const char* T_STATE = "casa/soggiorno/luce/stato";
const char* T_CMD   = "casa/soggiorno/luce/set";
const char* T_AVAIL = "casa/soggiorno/luce/online";
const int   RELAY   = 2;

WiFiClient net;
PubSubClient mqtt(net);

void publishState() {
  char payload[64];
  snprintf(payload, sizeof(payload), "{\"state\":\"%s\"}",
           digitalRead(RELAY) ? "ON" : "OFF");
  mqtt.publish(T_STATE, payload, true);        // retained
}

void onMessage(char* topic, byte* data, unsigned int len) {
  String msg;
  for (unsigned int i = 0; i < len; i++) msg += (char)data[i];
  digitalWrite(RELAY, msg.indexOf("ON") >= 0 ? HIGH : LOW);
  publishState();
}

void reconnect() {
  while (!mqtt.connected()) {
    // Last Will: se l'ESP32 sparisce, HomeHub lo vede offline
    if (mqtt.connect("esp32-soggiorno", nullptr, nullptr, T_AVAIL, 0, true, "offline")) {
      mqtt.publish(T_AVAIL, "online", true);
      mqtt.subscribe(T_CMD);
      publishState();
    } else {
      delay(2000);
    }
  }
}

void setup() {
  pinMode(RELAY, OUTPUT);
  WiFi.begin(SSID, PASS);
  while (WiFi.status() != WL_CONNECTED) delay(300);
  mqtt.setServer(BROKER, 1883);
  mqtt.setCallback(onMessage);
}

void loop() {
  if (!mqtt.connected()) reconnect();
  mqtt.loop();
}
```

